INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will MetaMask launch a token by September 30, 2026?', 'This market will resolve to "Yes" if Metamask officially launches a token by September 30, 2026, 11:59 PM ET. Otherwise, this market will resolve to "No". The token must be actively and publicly transferable and tradable. Announcements alone do not qualify The primary resolution source for this market will be information from Metamask, however a consensus of credible reporting will also be used. ', 'crypto', 'active', 12778.37, 488334.33, 13278.37, 488834.33);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Israel withdraws from Lebanon by August 31, 2026?', 'This market will resolve to "Yes" if Israel announces it has withdrawn all ground forces from Lebanon by the specified date, 11:59 PM ET. Otherwise, this market will resolve to "No". For this market to resolve to "Yes" it is sufficient that Israel announces its ground forces have withdrawn from all Lebanese territory, regardless of if some Lebanese territory remains under their control or ground incursions by Israeli forces continue. However, an announcement of a planned or future withdrawal wil', 'politics', 'active', 3688.48, 317048.89, 4188.48, 317548.89);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Iran full airspace closure by August 31?', 'This market will resolve to “Yes” if Iran initiates a general closure of its airspace, that is not solely due to weather conditions, between market creation and the specified date, 11:59 PM ET. Otherwise, this market will resolve to “No”. A “general closure” refers to a cancellation or suspension of aviation which is generally applicable to all commercial flights transiting Iranian airspace (“Tehran FIR”). A qualifying closure must apply generally to all of Iran or the Tehran FIR; limited cancel', 'world', 'active', 55781.47, 531391.87, 56281.47, 531891.87);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Strait of Hormuz traffic returns to normal by December 31?', 'This market will resolve to “Yes” if IMF Portwatch publishes a 7-day moving average of transit calls (“Arrivals of Ships”) for the Strait of Hormuz equal to or above 60 for any date between market creation and December 31, 2026. Otherwise, this market will resolve to “No”. Daily transit calls include container, dry bulk, roll-on/roll-off, general cargo, and tanker ships. Ships not reported by IMF Portwatch will not be considered. This market will resolve as soon as IMF Portwatch publishes a 7-da', 'politics', 'active', 1837425.3, 2114026.95, 1837925.3, 2114526.95);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will Ebuka Okorie win the 2026-27 NBA Rookie of the Year?', 'This market will resolve to the player who wins the Rookie of the Year award for the 2026-27 NBA regular season. In the event of a tie, this market will resolve according to the official winner as determined by NBA rules. If multiple winners are announced then this market will resolve to the player whose listed last name comes first alphabetically. If the 2026-27 NBA regular season is cancelled, postponed after April 30, 2027, 11:59 PM ET, or there is otherwise no winner declared within that tim', 'sports', 'active', 13029.56, 1289926.82, 13529.56, 1290426.82);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will there be at least 10000 measles cases in the U.S. in 2026?', 'This market will resolve to "Yes" if there have been the specified amount or more confirmed cases of Measles (Rubeola) in humans in the territory of the United States of America in 2026 according to the CDC case counter between January 1, 2026, 12:00 AM ET and December 31, 2026, 11:59 PM ET. Otherwise, this market will resolve to "No". The resolution source for this market will be the CDC Measles (Rubeola) counter (see: https://www.cdc.gov/measles/data-research/index.html) at the resolution time', 'tech', 'active', 188918.63, 3068299.2, 189418.63, 3068799.2);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will the US officially declare war on Iran by December 31, 2026?', 'This market will resolve to "Yes" if the United States formally declares war on Iran through an act of Congress between market creation and the specified date, 11:59 PM ET. Otherwise, this market will resolve to "No." To qualify, Congress must pass a formal declaration of war, consistent with its constitutional authority under Article I, Section 8. Authorizations for the use of military force (AUMFs), executive orders, presidential statements, or military actions do not qualify unless accompanie', 'politics', 'active', 12049.02, 383000.71, 12549.02, 383500.71);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will Base launch a token by December 31, 2026?', 'This market will resolve to "Yes" if Base officially launches a token by December 31, 2026, 11:59 PM ET. Otherwise, this market will resolve to "No". The token must be actively and publicly transferable and tradable. Announcements alone do not qualify The primary resolution source for this market will be information from Base, however a consensus of credible reporting will also be used. ', 'crypto', 'active', 32407.59, 308724.94, 32907.59, 309224.94);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will Israel strike 4 countries in 2026?', 'This market will resolve according to the total number of different countries'' soil that Israel initiates a drone, missile, or air strike between January 1, 2026, 12:00 AM ET and December 31, 2026, 11:59 PM ET. Strikes on embassies or consulates will count towards the country the embassy or consulate is located in, not towards the country they represent. Strikes within the territory controlled by Israel as of December 31, 2025, 11:59 PM ET, as well as strikes within the West Bank or the Gaza St', 'politics', 'active', 345651.05, 268293.98, 346151.05, 268793.98);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Fed rate hike in 2026?', 'This market will resolve to “Yes” if the upper bound of the target federal funds rate is increased at any point between January 1, 2026 and the Fed''s December 2026 meeting, currently scheduled for December 8-9, 2026. Otherwise, this market will resolve to “No”. This market may not resolve to "No" until the Fed has released its rate change decision following its December meeting. The primary resolution source for this market will be the official website of the Federal Reserve (https://www.federa', 'general', 'active', 1988477.46, 1660105.03, 1988977.46, 1660605.03);